// MIT. Offline bridge to the ORIGINAL generated SF30 request implementation.
import { createHash } from 'node:crypto';
// This companion is generated into the customer directory, not present in source.
const { buildRequest, source, operations } = await import(new URL('./seller-client.mjs', import.meta.url).href);

const MAX_INPUT = 64 * 1024 * 1024;
const MAX_BODY = 16 * 1024 * 1024;
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
function keys(value, allowed, name) {
  if (!object(value) || Object.keys(value).some(key => !allowed.includes(key)))
    throw new TypeError(`Invalid ${name}`);
}

async function main() {
  const chunks = []; let size = 0;
  for await (const chunk of process.stdin) {
    size += chunk.length;
    if (size > MAX_INPUT) throw new RangeError('Request input exceeds 64 MiB');
    chunks.push(chunk);
  }
  const input = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(Buffer.concat(chunks)));
  keys(input, ['sourceSha256', 'operationId', 'inputs', 'authorization'], 'request envelope');
  if (input.sourceSha256 !== source.sourceSha256) throw new TypeError('Original seller source changed');
  keys(input.authorization, ['intentId', 'maxAtomic', 'acceptIndex', 'paymentFlow'], 'authorization');
  keys(input.inputs, ['path', 'query', 'body', 'multipart', 'omitBody'], 'inputs');
  if (Object.hasOwn(input.inputs, 'multipart')) {
    const part = input.inputs.multipart;
    keys(part, ['bodyBase64', 'contentType'], 'retained multipart body');
    if (typeof part.bodyBase64 !== 'string' || part.bodyBase64.length > Math.ceil(MAX_BODY / 3) * 4)
      throw new TypeError('Retain a complete multipart body up to 16 MiB');
    const body = Buffer.from(part.bodyBase64, 'base64');
    if (body.toString('base64') !== part.bodyBase64 || body.length > MAX_BODY)
      throw new TypeError('Multipart body must use canonical complete base64');
    input.inputs.multipart = { body, contentType: part.contentType };
  }
  const request = buildRequest(input.operationId, input.inputs, input.authorization);
  const operation = operations.find(value => value.id === input.operationId);
  const { body, ...configuration } = request;
  const bytes = body === undefined ? null : typeof body === 'string' ? Buffer.from(body, 'utf8')
    : body instanceof Uint8Array ? Buffer.from(body) : (() => { throw new TypeError('Unknown original body representation'); })();
  if (bytes !== null && bytes.length > MAX_BODY) throw new RangeError('Original body exceeds 16 MiB');
  process.stdout.write(JSON.stringify({ schema: 'stellar-forge.ruby-seller-request.v1',
    sourceSha256: source.sourceSha256, operationId: operation.id,
    acceptIndex: input.authorization.acceptIndex ?? 0, request: configuration,
    body: bytes === null ? null : { bytes: bytes.length, sha256: sha(bytes), base64: bytes.toString('base64') } }) + '\n');
}
main().catch(error => {
  // Inputs, credentials, request bodies and stack traces are never echoed.
  process.stderr.write(JSON.stringify({ code: 'SELLER_REQUEST_INVALID', message: String(error.message) }) + '\n');
  process.exitCode = 1;
});

#!/usr/bin/env node
// MIT. Original retained repository, SF82 merchant and SF88 buyer commands.
import {readFile} from 'node:fs/promises';
import {resolve} from 'node:path';
import {pathToFileURL} from 'node:url';
import {openDspaceWorkspace,receiveDspaceWorkspace} from './workspace.mjs';
import {prepareDspaceMerchant,readDspaceMerchant,initializeDspaceVersions,startDspaceMerchant,
  publishDspaceMerchant,stageDspaceRelease,activateDspaceRelease,rollbackDspaceRelease,runDspaceRelease} from './merchant.mjs';
import {reviewDspaceBuyer,prepareDspaceBuyer,receiveDspaceBuyer,inspectDspaceDelivery,runDspaceBuyer} from './customer.mjs';
import {datasetControl} from '../dataset-refresh/service.mjs';
import {copyExact,object,fault} from './merchant-files.mjs';

const HELP=`Retained DSpace repository datasets
  state --workspace PRIVATE_DIRECTORY
  read --workspace PRIVATE_DIRECTORY --kind sources|editions|reviews|comparisons --id ID [--offset N --limit N]
  import-source --workspace PRIVATE_DIRECTORY --file ORIGINAL_CAPTURE.json --input REQUEST.json
  save-edition|review-edition|select-edition|compare-editions|record-publication --workspace PRIVATE_DIRECTORY --input REQUEST.json
  operation --workspace PRIVATE_DIRECTORY --id ORIGINAL_OPERATION_ID
  query --workspace PRIVATE_DIRECTORY --edition ID --input ORIGINAL_STRING_QUERY.json
  export-dataset --workspace PRIVATE_DIRECTORY --edition ID --out PRIVATE_DIRECTORY
  export --workspace PRIVATE_DIRECTORY --kind project|source|editions|dataset|config|reviews --id ID --out FILE
  receive --file COMPLETE_PROJECT.sqlite3 --workspace PRIVATE_DIRECTORY
  merchant prepare --workspace PRIVATE_DIRECTORY --edition ID --edition-sha SHA --review ID --package PRIVATE_DIRECTORY
       --versions PRIVATE_DIRECTORY --payment PUBLIC_TERMS.json --origin HTTPS_ORIGIN [--path /repository-data]
  merchant inspect|initialize --package PRIVATE_DIRECTORY
  merchant serve --package PRIVATE_DIRECTORY --stage PRIVATE_DIRECTORY [--runtime RUNTIME.json]
  merchant publish --package PRIVATE_DIRECTORY --expect SNAPSHOT --expect-revision N
  merchant status|collect --versions PRIVATE_DIRECTORY
  merchant activate --versions PRIVATE_DIRECTORY --snapshot SHA --expect SHA --expect-revision N
  merchant stage --package PRIVATE_DIRECTORY --releases PRIVATE_DIRECTORY --id ID [--label TEXT --runtime FILE]
  merchant release-activate --releases PRIVATE_DIRECTORY --id ID --input ORIGINAL_OPTIONS.json
  merchant release-rollback|release-run --releases PRIVATE_DIRECTORY --input ORIGINAL_OPTIONS.json
  buyer offer --package PRIVATE_DIRECTORY --seller http://127.0.0.1:PORT [--query QUERY.json]
  buyer prepare --package PRIVATE_DIRECTORY --seller http://127.0.0.1:PORT [--query QUERY.json]
       --intent ID --accept-index N --offer-sha SHA --out PRIVATE_BUYER.json
  buyer receive --package PRIVATE_DIRECTORY --session ORIGINAL_SESSION --out PRIVATE_DIRECTORY [--include-source-captures]
  buyer inspect-delivery --directory PRIVATE_DIRECTORY
  buyer init|status|run|recover|export|deliver|accounting|finalize ORIGINAL_SF88_OPTIONS

Request JSON retains actor, operationId and expectedRevision. Review also supplies
editionId, editionSha256, decision and comment. Exact source bytes are read from --file.
The original seller and buyer retain payment terms, per-page approvals and journals.
Use dspace-workspace for the industrial browser workspace.
`;
const print=value=>process.stdout.write(JSON.stringify(value,null,2)+'\n');
function flags(args,allowed,booleans=[]){
  const out={};
  for(let i=0;i<args.length;i++){
    const key=args[i];
    if(!allowed.includes(key)||Object.hasOwn(out,key))throw new TypeError('Unknown or repeated option: '+key);
    if(booleans.includes(key)){out[key]=true;continue;}
    if(!args[i+1]||args[i+1].startsWith('--'))throw new TypeError('A value is required for '+key);
    out[key]=args[++i];
  }return out;
}
const required=(f,k)=>{if(!f[k])throw new TypeError(k+' is required.');return f[k];};
const location=(f,k)=>resolve(required(f,k));
function integer(value,fallback){if(value===undefined)return fallback;if(!/^(0|[1-9][0-9]*)$/.test(value)||!Number.isSafeInteger(Number(value)))throw new TypeError('Use an exact nonnegative integer.');return Number(value);}
async function json(file,maximum=16*1024*1024){
  const raw=await readFile(file);if(raw.length>maximum)throw new TypeError('The input JSON exceeds its configured byte limit.');
  const value=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(raw));if(!object(value))throw new TypeError('The input JSON must be an object.');return value;
}
async function withWorkspace(f,run){
  const workspace=await openDspaceWorkspace({directory:location(f,'--workspace')});
  try{return await run(workspace);}finally{await workspace.close();}
}
function signals(service){
  let stopping=false;const stop=()=>{if(stopping)return;stopping=true;service.close().catch(e=>{process.stderr.write(e.message+'\n');process.exitCode=1;});};
  process.once('SIGINT',stop);process.once('SIGTERM',stop);return service;
}
async function merchant(args){
  const [action,...tokens]=args;
  if(!action||action==='--help'){process.stdout.write(HELP);return;}
  const allowed={
    prepare:['--workspace','--edition','--edition-sha','--review','--package','--versions','--payment','--origin','--path'],
    inspect:['--package'],initialize:['--package'],serve:['--package','--stage','--runtime'],
    publish:['--package','--expect','--expect-revision'],
    status:['--versions'],collect:['--versions'],activate:['--versions','--snapshot','--expect','--expect-revision'],
    stage:['--package','--releases','--id','--label','--runtime'],
    'release-activate':['--releases','--id','--input'],'release-rollback':['--releases','--input'],'release-run':['--releases','--input']
  }[action];if(!allowed)throw new TypeError(HELP);
  const f=flags(tokens,allowed);
  if(action==='inspect'){const p=await readDspaceMerchant(location(f,'--package'));return print({
    directory:p.directory,source:p.source,dataset:p.dataset,resource:p.service.publicOrigin+p.service.routes[0].path});}
  if(action==='initialize')return print(await initializeDspaceVersions(location(f,'--package')));
  if(action==='serve'){
    const service=await startDspaceMerchant({directory:location(f,'--package'),stageDirectory:location(f,'--stage'),
      runtime:f['--runtime']?await json(f['--runtime'],65536):{port:0}});
    print({url:service.url,mode:service.mode,edition:service.edition,current:service.versions.status(),stage:service.stageDirectory});
    return signals(service);
  }
  if(action==='publish')return print(await publishDspaceMerchant({directory:location(f,'--package'),
    expectedSnapshot:required(f,'--expect'),expectedRevision:integer(required(f,'--expect-revision'))}));
  if(['status','collect'].includes(action))return print(await datasetControl(location(f,'--versions'),action));
  if(action==='activate')return print(await datasetControl(location(f,'--versions'),'activate',{
    snapshot:required(f,'--snapshot'),expectedSnapshot:required(f,'--expect'),expectedRevision:integer(required(f,'--expect-revision'))}));
  if(action==='stage')return print(await stageDspaceRelease({directory:location(f,'--package'),
    releaseDirectory:location(f,'--releases'),id:required(f,'--id'),label:f['--label']??f['--id'],
    runtime:f['--runtime']?await json(f['--runtime'],65536):{port:0}}));
  const options=await json(required(f,'--input'),65536),directory=location(f,'--releases');
  if(action==='release-activate')return print(await activateDspaceRelease(directory,required(f,'--id'),options));
  if(action==='release-rollback')return print(await rollbackDspaceRelease(directory,options));
  return runDspaceRelease(directory,options);
}
async function buyer(args){
  if(['init','status','run','recover','export','deliver','accounting','finalize'].includes(args[0]))return runDspaceBuyer(args);
  const [action,...tokens]=args;
  const allowed={
    offer:['--package','--seller','--query'],
    prepare:['--package','--seller','--query','--intent','--accept-index','--offer-sha','--out'],
    receive:['--package','--session','--out','--include-source-captures'],
    'inspect-delivery':['--directory']
  }[action];if(!allowed)throw new TypeError(HELP);
  const f=flags(tokens,allowed,['--include-source-captures']);
  if(action==='inspect-delivery')return print(await inspectDspaceDelivery(location(f,'--directory')));
  if(action==='receive')return print(await receiveDspaceBuyer({directory:location(f,'--package'),
    sessionDirectory:location(f,'--session'),destination:location(f,'--out'),includeSourceCaptures:!!f['--include-source-captures']}));
  const input={directory:location(f,'--package'),seller:required(f,'--seller'),query:f['--query']?await json(f['--query'],16384):{}};
  if(action==='offer')return print(await reviewDspaceBuyer(input));
  return print(await prepareDspaceBuyer({...input,intentId:required(f,'--intent'),acceptIndex:integer(required(f,'--accept-index')),
    offerSha256:required(f,'--offer-sha'),destination:location(f,'--out')}));
}
export async function main(args=process.argv.slice(2)){
  if(!args.length||['--help','help','-h'].includes(args[0])){process.stdout.write(HELP);return;}
  if(args[0]==='merchant'){
    if(args[1]==='prepare'){
      const f=flags(args.slice(2),['--workspace','--edition','--edition-sha','--review','--package','--versions','--payment','--origin','--path']);
      const payment=await json(required(f,'--payment'),16384);
      return print(await withWorkspace(f,workspace=>prepareDspaceMerchant({workspace,
        editionId:required(f,'--edition'),editionSha256:required(f,'--edition-sha'),reviewId:required(f,'--review'),
        directory:location(f,'--package'),versionDirectory:location(f,'--versions'),payment,
        origin:required(f,'--origin'),path:f['--path']??'/repository-data'})));
    }
    return merchant(args.slice(1));
  }
  if(args[0]==='buyer')return buyer(args.slice(1));
  const [action,...tokens]=args,mutations=['save-edition','review-edition','select-edition','compare-editions','record-publication'];
  const allowed=mutations.includes(action)?['--workspace','--input']:{
    state:['--workspace'],read:['--workspace','--kind','--id','--offset','--limit'],
    operation:['--workspace','--id'],'import-source':['--workspace','--file','--input'],
    query:['--workspace','--edition','--input'],'export-dataset':['--workspace','--edition','--out'],
    export:['--workspace','--kind','--id','--out'],receive:['--workspace','--file']
  }[action];if(!allowed)throw new TypeError(HELP);const f=flags(tokens,allowed);
  if(action==='receive'){
    const ws=await receiveDspaceWorkspace({file:location(f,'--file'),directory:location(f,'--workspace')});
    try{return print(ws.state());}finally{await ws.close();}
  }
  return withWorkspace(f,async workspace=>{
    if(action==='state')return print(workspace.state());
    if(action==='read')return print(workspace.read(required(f,'--kind'),required(f,'--id'),{
      offset:integer(f['--offset'],0),limit:integer(f['--limit'],50)}));
    if(action==='operation')return print(workspace.operation(required(f,'--id')));
    if(action==='query')return print(await workspace.query(required(f,'--edition'),await json(required(f,'--input'))));
    if(action==='export-dataset')return print(await workspace.exportDataset(required(f,'--edition'),location(f,'--out')));
    if(action==='export'){
      const file=await workspace.exportFile(required(f,'--kind'),f['--id']);
      return print(await copyExact(file.path,location(f,'--out'),file));
    }
    const input=await json(required(f,'--input'));
    if(action==='import-source'){
      const raw=await readFile(location(f,'--file'));
      if(raw.length>256*1024*1024)throw fault('DSPACE_SOURCE_SIZE','Use the original source capture limit.');
      input.sourceBase64=raw.toString('base64');
    }
    return print(await workspace.dispatch(action,input));
  });
}
if(process.argv[1]&&import.meta.url===pathToFileURL(resolve(process.argv[1])).href)
  main().catch(error=>{process.stderr.write(JSON.stringify({error:error.code??'DSPACE_COMMAND',message:error.message})+'\n');process.exitCode=1;});

// MIT. DSpace customers use the original SF88 acquisition and SF100 data room.
import {join,resolve} from 'node:path';
import {readdir} from 'node:fs/promises';
import {scan as scanOriginalDataset} from '../../sf100-buyer-dataset-delivery/deliver.mjs';
import {readDspaceMerchant} from './merchant.mjs';
import {readDatasetBuyerOffer,prepareDatasetBuyer} from '../dataset-refresh/buyer-handoff.mjs';
import {inspectDatasetSession,deliverDatasetSession} from '../../sf88-operator-buyer-cli/dataset-session.mjs';
import {absolute,object,bytes,digest,identity,readJson,hashPrivate,privateDirectory,acquireWorkspace,
  fault,separated,saveExact,copyExact,descriptor,MiB} from './merchant-files.mjs';

function queryString(query){
  if(!object(query)||Object.entries(query).some(([key,value])=>typeof value!=='string'||['cursor','snapshot'].includes(key)))
    throw fault('DSPACE_BUYER_QUERY','Use original first-page string query parameters; the approved edition supplies snapshot.');
  const value=new URLSearchParams(Object.entries(query)).toString();
  if(value.length>8192)throw fault('DSPACE_BUYER_QUERY','The query exceeds the original buyer limit.');
  return value;
}
function editionSummary(prepared){
  return {workspace_id:prepared.source.workspace_id,id:prepared.source.edition.id,
    sha256:prepared.source.edition.sha256,snapshot:prepared.description.snapshot,
    row_count:prepared.description.rowCount,rights:prepared.source.rights,
    source_index_sha256:prepared.binding.sourceSha256,review:prepared.lineage.review};
}
export async function reviewDspaceBuyer({directory,seller,query={}}={}){
  const prepared=await readDspaceMerchant(directory);
  const resource=prepared.service.publicOrigin+prepared.service.routes[0].path;
  const review=await readDatasetBuyerOffer({seller,resource,snapshot:prepared.description.snapshot,query:queryString(query)});
  return {...review,edition:editionSummary(prepared)};
}
export async function prepareDspaceBuyer({directory,seller,query={},intentId,acceptIndex,offerSha256,destination}={}){
  const review=await reviewDspaceBuyer({directory,seller,query});
  const prepared=prepareDatasetBuyer(review,{intentId,acceptIndex,offerSha256});
  const content=Buffer.from(prepared.configText,'utf8');
  if(digest(content)!==prepared.configSha256)throw fault('DSPACE_BUYER_CONFIG','The original configuration identity differs.',409);
  const saved=await saveExact(absolute(destination,'buyer configuration file'),content);
  await saveExact(saved.path+'.dspace.json',{schema:'stellar-forge.dspace-buyer-selection.v1',
    edition:review.edition,url:prepared.url,offer_sha256:offerSha256,configuration_sha256:prepared.configSha256});
  return {...prepared,edition:review.edition,saved};
}

/** Complete original paid/free responses become a portable native data room.
 * The requested snapshot and original URL must match this exact approved edition.
 * Source captures are optional because they can include unpurchased repository objects. */
export async function receiveDspaceBuyer({directory,sessionDirectory,destination,includeSourceCaptures=false}={}){
  if(typeof includeSourceCaptures!=='boolean')throw new TypeError('includeSourceCaptures must be a boolean.');
  const prepared=await readDspaceMerchant(directory);
  sessionDirectory=absolute(sessionDirectory,'original buyer session');
  destination=absolute(destination,'customer delivery directory');
  separated(destination,prepared.directory);separated(destination,sessionDirectory);
  const report=await inspectDatasetSession(sessionDirectory);
  if(report.status!=='COMPLETE'||report.snapshot!==prepared.description.snapshot||!report.pages.length)
    throw fault('DSPACE_BUYER_COMPLETE','Complete the original acquisition of this exact retained edition.',409);
  const resource=prepared.service.publicOrigin+prepared.service.routes[0].path;
  for(const page of report.pages){
    const url=new URL(page.requestUrl);
    if(url.origin+url.pathname!==resource||url.searchParams.get('snapshot')!==prepared.description.snapshot)
      throw fault('DSPACE_BUYER_SOURCE_CHANGED','The acquisition belongs to another original resource or edition.',409);
  }
  await privateDirectory(destination,true);const unlock=await acquireWorkspace(destination);
  try{
    const intent={schema:'stellar-forge.dspace-customer-intent.v1',session_directory:sessionDirectory,
      session_id:report.sessionId,configuration_sha256:report.configurationSha256,
      edition:editionSummary(prepared),include_source_captures:includeSourceCaptures};
    await saveExact(join(destination,'receiving-intent.json'),intent);
    const native=await deliverDatasetSession(sessionDirectory,join(destination,'dataset'));
    const first=report.pages[0];
    const lineage={schema:'stellar-forge.dspace-customer-lineage.v1',
      edition:editionSummary(prepared),mode:prepared.source.mode,
      acquisition:{session_id:report.sessionId,snapshot:report.snapshot,pages:report.completedPages,
        rows:report.acquiredRows,configuration_sha256:report.configurationSha256,
        first_request_url:first.requestUrl,source_binding_sha256:native.sourceBindingSha256,
        original_exporter_blob:native.nativeBlob},
      sources:prepared.source.sources.map(({id,sha256,bytes,name,base_url,scope})=>({id,sha256,bytes,name,base_url,scope})),
      source_captures_included:includeSourceCaptures,
      review:prepared.lineage.review,rights:prepared.lineage.rights,
      payment_status:native.paymentStatus,
      original_outputs:Object.fromEntries(Object.entries(native.outputs).map(([name,file])=>
        [name,{path:'dataset/'+name,bytes:file.bytes,sha256:file.sha256}]))};
    const sources=[];
    if(includeSourceCaptures){
      // Explicit complete-source receiving preserves every reviewed provenance file
      // through the original descriptor list, including its original projection.
      for(const file of prepared.sourceFiles){
        const relative='source/'+file.path;
        await copyExact(join(prepared.directory,file.path),join(destination,relative),file);
        sources.push({...file,path:relative});
      }
      const originalSource=prepared.retained['source.json'];
      await saveExact(join(destination,'source/source.json'),originalSource);
      sources.push({path:'source/source.json',bytes:originalSource.length,sha256:digest(originalSource)});
    }
    await saveExact(join(destination,'dspace-lineage.json'),lineage);
    const nativeArchiveFiles=['dataset/session.json',...(await readdir(join(destination,'dataset/pages'))).sort().map(name=>'dataset/pages/'+name)];
    const archiveDescriptors=[];
    for(const name of nativeArchiveFiles)archiveDescriptors.push(await descriptor(destination,name));
    const files=[...archiveDescriptors,...Object.entries(native.outputs).map(([name,file])=>
      ({path:'dataset/'+name,bytes:file.bytes,sha256:file.sha256})),
      await descriptor(destination,'dspace-lineage.json'),...sources];
    files.sort((a,b)=>a.path.localeCompare(b.path));
    const manifest={schema:'stellar-forge.dspace-customer-delivery.v1',
      edition:editionSummary(prepared),source_binding_sha256:native.sourceBindingSha256,
      acquisition:{session_id:report.sessionId,pages:report.completedPages,rows:report.acquiredRows,
        native_buyer_statuses:[...new Set(report.pages.map(page=>page.nativeBuyerStatus))]},
      native_exporter_blob:native.nativeBlob,payment_status:native.paymentStatus,
      include_source_captures:includeSourceCaptures,files};
    manifest.sha256=identity(manifest);
    await saveExact(join(destination,'delivery.json'),manifest);
    return {...await inspectDspaceDelivery(destination),native};
  }finally{await unlock();}
}
export async function inspectDspaceDelivery(directory){
  directory=absolute(directory,'original delivery directory');await privateDirectory(directory);
  const manifest=await readJson(join(directory,'delivery.json'),8*MiB),unsigned={...manifest};delete unsigned.sha256;
  if(manifest.schema!=='stellar-forge.dspace-customer-delivery.v1'||identity(unsigned)!==manifest.sha256||
      !Array.isArray(manifest.files)||manifest.files.length>25000)
    throw fault('DSPACE_DELIVERY_FORMAT','Choose a complete original repository customer delivery.');
  const names=new Set();
  for(const file of manifest.files){
    if(typeof file.path!=='string'||file.path.includes('\\')||file.path.startsWith('/')||
        file.path.split('/').some(p=>!p||p==='.'||p==='..')||names.has(file.path))
      throw fault('DSPACE_DELIVERY_PATH','The original delivery contains an invalid or duplicate file path.');
    names.add(file.path);
    const actual=await hashPrivate(join(directory,file.path),512*MiB);
    if(actual.bytes!==file.bytes||actual.hash!==file.sha256)
      throw fault('DSPACE_DELIVERY_CHANGED','A retained original customer file differs from its digest.',409);
  }
  const lineage=await readJson(join(directory,'dspace-lineage.json'),16*MiB);
  if(lineage.edition.sha256!==manifest.edition.sha256||lineage.acquisition.snapshot!==manifest.edition.snapshot||
      lineage.acquisition.source_binding_sha256!==manifest.source_binding_sha256)
    throw fault('DSPACE_DELIVERY_CHANGED','The customer lineage differs from the original source binding.',409);
  const native=await scanOriginalDataset(join(directory,'dataset'),{retainPayload:false});
  const originalManifest=await readJson(join(directory,'dataset/manifest.json'),4*MiB);
  if(native.snapshot!==manifest.edition.snapshot||native.pages.length!==manifest.acquisition.pages||native.count!==manifest.acquisition.rows||native.total!==manifest.acquisition.rows||
      native.chain!==originalManifest.chainDigest||!native.finalized)
    throw fault('DSPACE_NATIVE_DELIVERY_CHANGED','The original buyer page chain differs from this complete delivery.',409);
  return {directory,manifest,lineage,native:{snapshot:native.snapshot,pages:native.pages.length,rows:native.count,chain:native.chain},bytes:manifest.files.reduce((sum,file)=>sum+file.bytes,0)};
}

/** These entrypoints retain the original operator, signer, budgets and per-page review. */
export async function runDspaceBuyer(args){return(await import('../../sf88-operator-buyer-cli/dataset-cli.mjs')).main(args);}

// MIT. Atomic exact private-file receiving for the DSpace adapter.
import {constants} from 'node:fs';
import {open,link,unlink,mkdir,lstat,realpath} from 'node:fs/promises';
import {dirname,resolve,relative,sep} from 'node:path';
import {randomUUID,createHash} from 'node:crypto';
export {absolute,object,bytes,digest,identity,readPrivate,readJson,hashPrivate,
