      throw fault('PACKAGE_NUMBER_REQUIRES_EXACT_STRING');
    if (spec.type === 'boolean' && !['true', 'false'].includes(value)) throw fault('PACKAGE_BOOLEAN_PROJECTION_INVALID');
    return value;
  }));
}

