  if(!Number.isInteger(port)||port<0||port>65535)throw error('PORT_INVALID','Use a port from 0 to 65535.');
  if(!Number.isSafeInteger(maxRequestBytes)||maxRequestBytes<1024||maxRequestBytes>1024*1024*1024)
